<script setup>
import { onMounted, reactive, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { createGoods, deleteGoods, getAdminGoods, updateGoods } from '@/api/admin'
import { getCategories } from '@/api/goods'

const list = ref([]); const total = ref(0); const categories = ref([]); const loading = ref(false); const page = ref(1); const keyword = ref(''); const dialog = ref(false); const editingId = ref(null); const formRef = ref()
const form = reactive({ name: '', category_id: '', price: 0, original_price: 0, stock: 0, sales: 0, image: '', description: '', status: 1 })
const rules = { name: [{ required: true, message: '请输入商品名称', trigger: 'blur' }], category_id: [{ required: true, message: '请选择分类', trigger: 'change' }], price: [{ required: true, message: '请输入销售价格', trigger: 'blur' }], stock: [{ required: true, message: '请输入库存', trigger: 'blur' }] }
async function load() { loading.value = true; try { const data = await getAdminGoods({ page: page.value, pageSize: 10, keyword: keyword.value || undefined }); list.value = data.list; total.value = data.total } finally { loading.value = false } }
function open(item = null) { editingId.value = item?.id || null; Object.assign(form, item ? { ...item } : { name: '', category_id: '', price: 0, original_price: 0, stock: 0, sales: 0, image: '', description: '', status: 1 }); dialog.value = true }
async function save() { await formRef.value.validate(); if (editingId.value) await updateGoods(editingId.value, form); else await createGoods(form); ElMessage.success(editingId.value ? '商品已更新' : '商品已新增'); dialog.value = false; await load() }
async function remove(id) { await ElMessageBox.confirm('确认永久删除该商品吗？已有订单的商品不可删除，建议改为下架。', '删除商品', { type: 'warning' }); await deleteGoods(id); ElMessage.success('商品已删除'); await load() }
async function toggleStatus(row) { await updateGoods(row.id, row); ElMessage.success(row.status ? '商品已上架' : '商品已下架') }
async function search() { page.value = 1; await load() }
onMounted(async () => { categories.value = await getCategories(); await load() })
</script>

<template><section class="admin-content"><div class="admin-title"><div><span>CATALOG MANAGEMENT</span><h1>商品管理</h1><p>新增、编辑、上下架或删除商城商品。</p></div><el-button type="primary" @click="open()">新增商品</el-button></div><div class="admin-tools"><el-input v-model="keyword" placeholder="按商品名称搜索" clearable @keyup.enter="search" @clear="search"><template #append><el-button @click="search">搜索</el-button></template></el-input></div><el-table v-loading="loading" :data="list" class="goods-table"><el-table-column label="商品" min-width="220"><template #default="{ row }"><div class="table-product"><img :src="row.image" :alt="row.name" /><span><b>{{ row.name }}</b><small>{{ row.category_name }}</small></span></div></template></el-table-column><el-table-column label="价格" width="110"><template #default="{ row }">¥{{ Number(row.price).toFixed(2) }}</template></el-table-column><el-table-column prop="stock" label="库存" width="80" /><el-table-column prop="sales" label="销量" width="80" /><el-table-column label="状态" width="100"><template #default="{ row }"><el-switch v-model="row.status" :active-value="1" :inactive-value="0" @change="toggleStatus(row)" /></template></el-table-column><el-table-column label="操作" width="145" fixed="right"><template #default="{ row }"><el-button link type="primary" @click="open(row)">编辑</el-button><el-button link type="danger" @click="remove(row.id)">删除</el-button></template></el-table-column></el-table><div class="admin-pagination"><el-pagination background layout="prev, pager, next" :current-page="page" :page-size="10" :total="total" @current-change="page = $event; load()" /></div></section><el-dialog v-model="dialog" :title="editingId ? '编辑商品' : '新增商品'" width="680px" destroy-on-close><el-form ref="formRef" :model="form" :rules="rules" label-width="5rem"><el-row :gutter="16"><el-col :span="12"><el-form-item label="商品名称" prop="name"><el-input v-model="form.name" /></el-form-item></el-col><el-col :span="12"><el-form-item label="商品分类" prop="category_id"><el-select v-model="form.category_id" style="width: 100%"><el-option v-for="item in categories" :key="item.id" :label="item.name" :value="item.id" /></el-select></el-form-item></el-col><el-col :span="8"><el-form-item label="售价" prop="price"><el-input-number v-model="form.price" :min="0" :precision="2" style="width: 100%" /></el-form-item></el-col><el-col :span="8"><el-form-item label="原价"><el-input-number v-model="form.original_price" :min="0" :precision="2" style="width: 100%" /></el-form-item></el-col><el-col :span="8"><el-form-item label="库存" prop="stock"><el-input-number v-model="form.stock" :min="0" :precision="0" style="width: 100%" /></el-form-item></el-col></el-row><el-form-item label="图片地址"><el-input v-model="form.image" placeholder="https://..." /></el-form-item><el-form-item label="商品描述"><el-input v-model="form.description" type="textarea" :rows="3" /></el-form-item><el-form-item label="上架状态"><el-switch v-model="form.status" :active-value="1" :inactive-value="0" /></el-form-item></el-form><template #footer><el-button @click="dialog = false">取消</el-button><el-button type="primary" @click="save">保存商品</el-button></template></el-dialog></template>

<style scoped>
.admin-content { padding: clamp(1.2rem, 3vw, 2rem); }.admin-title { display: flex; align-items: center; justify-content: space-between; gap: 1rem; }.admin-title > div > span { color: #ec6a42; font-size: .65rem; font-weight: 800; letter-spacing: .14em; }.admin-title h1 { margin: .25rem 0; font-size: 1.55rem; letter-spacing: -.05em; }.admin-title p { margin: 0; color: #98a2b3; font-size: .85rem; }.admin-title :deep(.el-button--primary), :deep(.el-button--primary) { background: #ec552f; border-color: #ec552f; }.admin-tools { width: min(100%, 22rem); margin: 1.5rem 0 1rem; }.goods-table { width: 100%; }.table-product { display: flex; align-items: center; gap: .65rem; }.table-product img { width: 2.8rem; height: 2.8rem; border-radius: .4rem; object-fit: cover; }.table-product span { display: grid; gap: .25rem; min-width: 0; }.table-product b { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }.table-product small { color: #98a2b3; }.admin-pagination { display: flex; justify-content: flex-end; padding-top: 1.2rem; }
@media (max-width: 580px) { .admin-title { align-items: flex-end; }.admin-title p { display: none; }.admin-content { padding: 1rem; }.admin-pagination { justify-content: center; } }
</style>
